import React, { useState } from 'react';
import axios from 'axios';
import { Toaster, toast } from 'react-hot-toast';
import { MapPin, Thermometer, TrendingUp, Satellite, BarChart3, AlertTriangle } from 'lucide-react';
import GoogleMapComponent from './components/GoogleMap';
import TemperatureChart from './components/TemperatureChart';
import SatelliteImagery from './components/SatelliteImagery';
import HeatZoneAnalysis from './components/HeatZoneAnalysis';
import './App.css';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5001';

function App() {
  const [city, setCity] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!city.trim()) {
      setError('Please enter a city name');
      return;
    }

    setLoading(true);
    setError('');
    setResult(null);

    try {
      const response = await axios.post(`${API_BASE_URL}/api/uhi-analysis`, {
        city: city.trim()
      });

      setResult(response.data);
    } catch (err) {
      if (err.response?.data?.error) {
        setError(err.response.data.error);
      } else {
        setError('Failed to analyze city. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  const getUHILevelColor = (level) => {
    switch (level) {
      case 'High': return 'text-red-600 bg-red-100';
      case 'Medium': return 'text-orange-600 bg-orange-100';
      case 'Low': return 'text-green-600 bg-green-100';
      default: return 'text-gray-600 bg-gray-100';
    }
  };

  const getAQIColor = (aqi) => {
    if (aqi <= 50) return 'text-green-600 bg-green-100';
    if (aqi <= 100) return 'text-yellow-600 bg-yellow-100';
    if (aqi <= 150) return 'text-orange-600 bg-orange-100';
    if (aqi <= 200) return 'text-red-600 bg-red-100';
    return 'text-purple-600 bg-purple-100';
  };

  const getTemperatureColor = (temp) => {
    if (temp >= 35) return 'text-red-600';
    if (temp >= 30) return 'text-orange-600';
    if (temp >= 25) return 'text-yellow-600';
    return 'text-green-600';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-green-50">
      {/* Header */}
      <header className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="text-center">
            <h1 className="text-4xl font-bold text-gray-900 mb-2">
              🌡️ Urban Heat Island Detector
            </h1>
            <p className="text-lg text-gray-600">
              AI-powered climate analysis for Indian cities
            </p>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Search Form */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-8">
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="city" className="block text-sm font-medium text-gray-700 mb-2">
                Enter City Name
              </label>
              <div className="flex space-x-4">
                <input
                  type="text"
                  id="city"
                  value={city}
                  onChange={(e) => setCity(e.target.value)}
                  placeholder="e.g., Delhi, Mumbai, Bangalore..."
                  className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  disabled={loading}
                />
                <button
                  type="submit"
                  disabled={loading}
                  className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {loading ? 'Analyzing...' : 'Analyze'}
                </button>
              </div>
            </div>
          </form>

          {error && (
            <div className="mt-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
              {error}
            </div>
          )}
        </div>

        {/* Results */}
        {result && (
          <div className="space-y-6">
            {/* City Overview */}
            <div className="bg-white rounded-lg shadow-lg p-6">
              <h2 className="text-2xl font-bold text-gray-900 mb-4">
                📍 {result.city} Analysis
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {/* Temperature */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-2xl">🌡️</span>
                    <span className="text-sm font-medium text-gray-600">Temperature</span>
                  </div>
                  <div className={`text-2xl font-bold ${getTemperatureColor(result.temperature)}`}>
                    {result.temperature}°C
                  </div>
                  <div className="text-sm text-gray-500 capitalize">
                    {result.weather_description}
                  </div>
                </div>

                {/* AQI */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-2xl">🌫️</span>
                    <span className="text-sm font-medium text-gray-600">Air Quality</span>
                  </div>
                  <div className={`text-2xl font-bold ${getAQIColor(result.aqi).split(' ')[0]}`}>
                    {result.aqi}
                  </div>
                  <div className={`text-sm px-2 py-1 rounded-full inline-block ${getAQIColor(result.aqi)}`}>
                    {result.aqi_interpretation}
                  </div>
                </div>

                {/* Humidity */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-2xl">💧</span>
                    <span className="text-sm font-medium text-gray-600">Humidity</span>
                  </div>
                  <div className="text-2xl font-bold text-blue-600">
                    {result.humidity}%
                  </div>
                </div>

                {/* Wind Speed */}
                <div className="bg-gray-50 rounded-lg p-4">
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="text-2xl">💨</span>
                    <span className="text-sm font-medium text-gray-600">Wind Speed</span>
                  </div>
                  <div className="text-2xl font-bold text-gray-600">
                    {result.wind_speed} m/s
                  </div>
                </div>
              </div>
            </div>

            {/* UHI Risk Assessment */}
            <div className="bg-white rounded-lg shadow-lg p-6">
              <h3 className="text-xl font-bold text-gray-900 mb-4">
                🔥 Urban Heat Island Risk Assessment
              </h3>

              <div className="flex items-center space-x-4 mb-4">
                <span className="text-lg font-medium text-gray-700">Risk Level:</span>
                <span className={`px-4 py-2 rounded-full font-bold text-lg ${getUHILevelColor(result.uhi_level)}`}>
                  {result.uhi_level}
                </span>
              </div>

              <div className="bg-gray-50 rounded-lg p-4">
                <h4 className="font-semibold text-gray-900 mb-2">🌱 Recommended Actions</h4>
                <div className="mb-4">
                  <span className="text-lg font-bold text-green-600">
                    Plant {result.recommended_trees.toLocaleString()} trees
                  </span>
                  <span className="text-gray-600 ml-2">in urban areas</span>
                </div>

                <div className="space-y-2">
                  <h5 className="font-medium text-gray-800">Adaptation Measures:</h5>
                  <ul className="space-y-1">
                    {result.measures.map((measure, index) => (
                      <li key={index} className="flex items-start space-x-2">
                        <span className="text-green-500 mt-1">✓</span>
                        <span className="text-gray-700">{measure}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            {/* Additional Info */}
            <div className="bg-blue-50 rounded-lg p-4">
              <div className="flex items-center space-x-2 mb-2">
                <span className="text-lg">ℹ️</span>
                <span className="font-medium text-blue-900">Analysis Information</span>
              </div>
              <p className="text-blue-800 text-sm">
                Analysis completed at {new Date(result.timestamp).toLocaleString()}. 
                This assessment helps identify urban heat island effects and provides 
                climate adaptation recommendations for sustainable urban development.
              </p>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-gray-800 text-white py-8 mt-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <p className="text-gray-300">
            Urban Heat Island Detector - AI-powered climate analysis for Indian cities
          </p>
          <p className="text-gray-400 text-sm mt-2">
            Built for sustainable urban development and climate adaptation
          </p>
        </div>
      </footer>
    </div>
  );
}

export default App;
